#!/usr/bin/env bash
# Build the own minimal C-shared sing-box v1.14.4 libbox shim.
#
# This is NOT gomobile. dart:ffi binds the flat C ABI exported by main.go,
# with declarations generated by ffigen from libbox_shim.h (committed ABI).
#
# Native binaries are build artifacts and are gitignored; CI builds and ships
# them. If an artifact is absent the app silently falls back to Socket.connect
# (D-07; implemented in plan 19-03).
set -euo pipefail

SHIM_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MOBILE_DIR="$(cd "${SHIM_DIR}/../.." && pwd)"
LIBBOX_VERSION="1.14.4"
BUILD_TAGS="with_gvisor,with_quic,with_wireguard,with_utls,with_naive_outbound,with_clash_api,badlinkname,tfogo_checklinkname0"
# with_utls is required for Reality. -checklinkname=0 is required by sing-box.
LDFLAGS="-X github.com/sagernet/sing-box/constant.Version=${LIBBOX_VERSION} -s -w -buildid= -checklinkname=0"
HEADER_OUT="${SHIM_DIR}/libbox_shim.h"

go_build() {
  local cc="$1"
  local out="$2"
  local cflags="${3:-}"
  local extra_ldflags="${4:-}"
  local header="${out%.*}.h"

  mkdir -p "$(dirname "${out}")"
  CGO_ENABLED=1 CC="${cc}" CGO_CFLAGS="${cflags}" CGO_LDFLAGS="${cflags}" \
    go build -trimpath -buildmode=c-shared -tags "${BUILD_TAGS}" \
      -ldflags "${LDFLAGS} ${extra_ldflags}" -o "${out}" "${SHIM_DIR}"

  # Refresh the committed C ABI contract used by ffigen.
  if [ -f "${header}" ]; then
    cp "${header}" "${HEADER_OUT}"
  fi
}

build_host() {
  local out="${MOBILE_DIR}/build/libboxshim.dylib"
  go_build "$(command -v clang)" "${out}"
  echo "host dylib: ${out}"
}

build_android() {
  local ndk="${ANDROID_NDK_HOME:-${ANDROID_NDK_ROOT:-}}"
  if [ -z "${ndk}" ]; then
    echo "SKIP Android: ANDROID_NDK_HOME is not set." >&2
    echo "CI requires OpenJDK 17 + Android SDK and produces arm64-v8a and" >&2
    echo "armeabi-v7a .so files into android/app/src/main/jniLibs/<abi>/." >&2
    return 0
  fi

  local host_tag
  case "$(uname -s)" in
    Darwin) host_tag="darwin-x86_64" ;;
    Linux) host_tag="linux-x86_64" ;;
    *) echo "Unsupported Android build host: $(uname -s)" >&2; return 1 ;;
  esac

  local api="24"
  local abi triple cc out
  for abi in arm64-v8a armeabi-v7a; do
    case "${abi}" in
      arm64-v8a) triple="aarch64-linux-android" ;;
      armeabi-v7a) triple="armv7a-linux-androideabi" ;;
    esac
    cc="${ndk}/toolchains/llvm/prebuilt/${host_tag}/bin/${triple}${api}-clang"
    if [ ! -x "${cc}" ]; then
      echo "SKIP ${abi}: compiler not found at ${cc}" >&2
      continue
    fi
    out="${MOBILE_DIR}/android/app/src/main/jniLibs/${abi}/libboxshim.so"
    go_build "${cc}" "${out}" "--target=${triple}${api} -fPIC"
    echo "android ${abi}: ${out}"
  done
}

build_ios() {
  if ! command -v xcrun >/dev/null 2>&1; then
    echo "SKIP iOS: xcrun is not available on this host." >&2
    return 0
  fi

  local sdk cc out
  sdk="$(xcrun -sdk iphoneos -show-sdk-path)"
  cc="$(xcrun -sdk iphoneos -find clang)"
  out="${MOBILE_DIR}/build/ios-arm64/libboxshim.dylib"
  local flags="-arch arm64 -isysroot ${sdk} -miphoneos-version-min=15.0"
  go_build "${cc}" "${out}" "${flags}" "-extldflags=${flags}"
  echo "iOS arm64: ${out} (CI wraps it into a .xcframework; no NetworkExtension needed for urltest-only)"
}

case "${1:-host}" in
  host) build_host ;;
  android) build_android ;;
  ios) build_ios ;;
  all)
    build_host
    build_android
    build_ios
    ;;
  *)
    echo "Usage: $0 {host|android|ios|all}" >&2
    exit 2
    ;;
esac
